    {"id":"C","kind":"point","role":"given point inside the solution","label":"C"},
    {"id":"boundaryLabel","kind":"label","role":"derived boundary equation","label":"x = 3"}
  ],
  "constructions": [
    {"id":"makeAxes","operator":"axes","inputs":{"xMin":0,"xMax":7,"yMin":-4,"yMax":6},"outputs":["axes"]},
    {"id":"makeSolution","operator":"linear_half_plane","inputs":{"variables":["x","y"],"inequality":"5 - 3*x <= 2*x - 10"},"outputs":["solution"]},
    {"id":"makeA","operator":"point","inputs":{"x":"ax","y":"ay","coordinateSpace":"world"},"outputs":["A"]},
    {"id":"makeB","operator":"point","inputs":{"x":"bx","y":"by","coordinateSpace":"world"},"outputs":["B"]},
    {"id":"makeC","operator":"point","inputs":{"x":"cx","y":"cy","coordinateSpace":"world"},"outputs":["C"]},
    {"id":"makeBoundaryLabel","operator":"label","inputs":{"target":"solution","text":"x = 3"},"outputs":["boundaryLabel"]}
  ],
  "relations": [],
  "assertions": [],
  "annotations": [],
