  ],
  "teachingTimeline": [
    {"revealGroupId":"setup","narrationCue":"Graph the inclusive inequality and mark the three given points. There is no restriction on y."},
    {"revealGroupId":"result","narrationCue":"Rearranging gives x ≥ 3. The boundary is x = 3: A lies on it and belongs to the solution; B is outside; C is inside."}
  ]
}

